[tasks.extract-execution]
shell = "node --input-type=module-typescript -e"
run = '''
const {readFileSync,writeFileSync,createReadStream} = await import('node:fs');
const {createInterface} = await import('node:readline');
const {execFileSync} = await import('node:child_process');
const {createHash} = await import('node:crypto');
const {homedir} = await import('node:os');
const {join} = await import('node:path');
const {strictEqual,deepStrictEqual} = await import('node:assert');
const runId=process.env.DEPOT_ACCOUNTING_RUN;
if(!runId||!/^[a-z0-9]+$/.test(runId))throw new Error('Run ID required');
const directory=`collected-${runId}`;
const collection=JSON.parse(readFileSync(`${directory}/collection.json`,'utf8'));
const executions=[];
for(const attempt of collection.attempts){
  const events=[],prefixedEventLines=[];
  for await(const line of createInterface({input:createReadStream(`${directory}/${attempt.logPath}`),crlfDelay:Infinity})){
    if(!line)continue;
    const row=JSON.parse(line),start=row.body?.indexOf('{"schemaVersion":1,')??-1;
    if(start<0)continue;
    const event=JSON.parse(row.body.slice(start));
    if(event.event==='check-finished'||event.event==='case-finished')events.push(event);
    if(start>0)prefixedEventLines.push({timestamp:row.timestamp,prefix:row.body.slice(0,start)});
  }
  const summaries=events.filter(row=>row.event==='case-finished');
  let summarySource='provider-log';
  if(summaries.length===0&&process.env.DEPOT_ACCOUNTING_ARTIFACT_SUMMARY){
    summaries.push(JSON.parse(readFileSync(process.env.DEPOT_ACCOUNTING_ARTIFACT_SUMMARY,'utf8')));
    summarySource='downloaded-provider-artifact';
  }
  if(summaries.length===0){console.log(JSON.stringify({attemptId:attempt.attemptId,caseFinished:false}));continue;}
  strictEqual(summaries.length,1);
  const summary=summaries[0];
  const manifestBytes=execFileSync('git',['-C',join(homedir(),'Monochromatic'),'show',`${collection.revision}:.depot/manifests/${summary.caseId}.json`],{maxBuffer:32*1024*1024});
  const digest=createHash('sha256').update(manifestBytes).digest('hex');
  strictEqual(summary.manifestSha256,digest);
  const manifest=JSON.parse(manifestBytes);
  strictEqual(summary.sourceRevision,manifest.sourceRevision);
  deepStrictEqual(summary.selectedCheckIds,manifest.checks.map(row=>row.id));
  deepStrictEqual(summary.results.map(row=>row.checkId).toSorted(),manifest.checks.map(row=>row.id).toSorted());
  const finished=events.filter(row=>row.event==='check-finished'&&Array.isArray(row.selectedCheckIds));
  const supplementalResults=events.filter(row=>row.event==='check-finished'&&!Array.isArray(row.selectedCheckIds));
  for(const result of supplementalResults){
    const spec=[...manifest.checks,...(manifest.externalChecks??[])].find(row=>row.id===result.checkId);
    if(!spec)throw new Error(`Supplemental check outside manifest ${result.checkId}`);
    strictEqual(result.task,spec.task);deepStrictEqual(result.args,spec.args??[]);
    strictEqual(result.sourceRevision,manifest.sourceRevision);strictEqual(result.manifestSha256,digest);
  }
  strictEqual(new Set(finished.map(row=>row.checkId)).size,finished.length);
  const missingLogResults=summary.results.filter(row=>!finished.some(event=>event.checkId===row.checkId)).map(row=>row.checkId);
  if(summarySource==='provider-log')deepStrictEqual(finished.toSorted((a,b)=>a.checkId.localeCompare(b.checkId)),summary.results.toSorted((a,b)=>a.checkId.localeCompare(b.checkId)));
  else for(const event of finished)deepStrictEqual(event,summary.results.find(row=>row.checkId===event.checkId));
  for(const result of summary.results){
    const spec=manifest.checks.find(row=>row.id===result.checkId);
    strictEqual(result.task,spec.task);deepStrictEqual(result.args,spec.args);
    strictEqual(result.sourceRevision,manifest.sourceRevision);strictEqual(result.manifestSha256,digest);
  }
  writeFileSync(`${directory}/execution-${attempt.attemptId}.json`,JSON.stringify({...summary,attemptIds:[attempt.attemptId]},null,2)+'\n');
  writeFileSync(`${directory}/manifest-${attempt.attemptId}.json`,manifestBytes);
  const outcomes=summary.results.map(row=>({id:row.checkId,status:row.status,seconds:row.elapsedMs/1000,expectedFiles:row.expectedFiles?.length??null}));
  const result={runId,attemptId:attempt.attemptId,workflowRevision:collection.revision,sourceRevision:summary.sourceRevision,manifestSha256:digest,completeGraph:summary.completeGraph,summarySource,missingLogResults,outcomes,supplementalResults,externalChecks:manifest.externalChecks?.map(row=>row.id),deferredChecks:summary.deferredChecks,prefixedEventLines,limitation:'Task invocation and result identities verified. Retained log events must match the summary; absent log events remain explicit. Supplemental results are distinct attempts and do not overwrite deferred records. Individual passing case/artifact completeness is not inferred from exit codes.'};
  executions.push(result);
  console.log(JSON.stringify({runId,attemptId:attempt.attemptId,sourceRevision:summary.sourceRevision,manifestSha256:digest,summarySource,missingLogResults:missingLogResults.length,counts:Object.fromEntries(['passed','failed','skipped'].map(status=>[status,outcomes.filter(row=>row.status===status).length])),prefixedEvents:prefixedEventLines.length}));
}
writeFileSync(`${directory}/execution-reconciliation.json`,JSON.stringify(executions,null,2)+'\n');
'''

