[tasks.group-logger-diagnostics]
shell = "node --input-type=module-typescript -e"
run = '''
const {readFileSync,writeFileSync,createReadStream}=await import('node:fs');
const {createInterface}=await import('node:readline');
const dir='collected-qm7w64tmhj';
const results=JSON.parse(readFileSync(`${dir}/artifact/logger-results.json`,'utf8')).results;
const groups=new Map();
for await(const line of createInterface({input:createReadStream(`${dir}/logs-5b9mnld66v.jsonl`),crlfDelay:Infinity})){
  if(!line)continue;
  const row=JSON.parse(line),body=(row.body??'').replace(/\x1b\[[0-9;]*m/g,'');
  if(!/^\S.*\(\d+,\d+\): error TS\d+:|^\s*× |^Error:|^error\[E\d+\]/.test(body))continue;
  const code=body.match(/\bTS\d+\b|\bERR_[A-Z_]+\b|\bE\d{4}\b/)?.[0]??body.match(/×\s+([^:]+):/)?.[1]??'unclassified-error';
  const group=groups.get(code)??{code,count:0,examples:[],candidateCheckIds:new Set()};
  group.count++;
  const timestamp=Date.parse(row.timestamp);
  const candidates=results.filter(check=>check.status!=='skipped'&&Date.parse(check.startedAt)<=timestamp&&Date.parse(check.finishedAt)>=timestamp).map(check=>check.checkId);
  for(const id of candidates)group.candidateCheckIds.add(id);
  if(group.examples.length<12&&!group.examples.some(example=>example.body===body))group.examples.push({timestamp:row.timestamp,lineNumber:row.line_number,body,candidateCheckIds:candidates});
  groups.set(code,group);
}
