[tasks.verify-native-results]
shell = "node --input-type=module-typescript -e"
run = '''
const {readFileSync,writeFileSync}=await import('node:fs');
const {createHash}=await import('node:crypto');
const {strictEqual,deepStrictEqual}=await import('node:assert');
const specs=[['38844610546',1432,1432,0,1],['38843527788',1433,1017,3,1],['38842787230',1382,54,1,1]];
for(const [runId,total,passed,failed,skipped]of specs){
  const dir=`github-${runId}`,collection=JSON.parse(readFileSync(`${dir}/collection.json`,'utf8'));
  const jobs=collection.jobs.map(job=>{
    const lines=readFileSync(`${dir}/${job.log.path}`,'utf8').split('\n').map(line=>line.replace(/\x1b\[[0-9;]*m/g,'').replace(/^\S+Z /,'').trim());
    const records=lines.map(line=>line.match(/^(PASS|FAIL) \[\s*[^\]]+\]\s+\(\s*(\d+)\/(\d+)\)\s+(.+)$/)).filter(Boolean);
    if(runId==='38842787230'&&job.name.includes('windows')){
      strictEqual(records.length,0);
      const diagnostics=lines.filter(line=>/^error\[E0433\]:/.test(line));strictEqual(diagnostics.length,4);
      return {jobId:job.id,name:job.name,executedTests:0,compileFailed:true,diagnostics,seconds:job.seconds};
    }
    // Nextest repeats failed records after its summary; retain the original numbered execution entries once.
    const unique=new Map();
    for(const record of records){const prior=unique.get(record[4]);if(prior)deepStrictEqual(prior,record.slice(1));else unique.set(record[4],record.slice(1));}
    const rows=[...unique.values()];
    strictEqual(rows.length,passed+failed);
    strictEqual(rows.filter(row=>row[0]==='PASS').length,passed);strictEqual(rows.filter(row=>row[0]==='FAIL').length,failed);
    strictEqual(rows.every(row=>Number(row[2])===total),true);
    deepStrictEqual(rows.map(row=>Number(row[1])).toSorted((a,b)=>a-b),Array.from({length:rows.length},(_,index)=>index+1));
    const summaries=lines.filter(line=>/^Summary \[/.test(line));strictEqual(summaries.length,1);
    strictEqual(summaries[0].includes(`${passed} passed`),true);strictEqual(summaries[0].includes(`${skipped} skipped`),true);
    const identities=rows.map(row=>row[3]).toSorted();
    return {jobId:job.id,name:job.name,passed,failed,skipped,executedTests:rows.length,selectedNonignoredTests:total,unexecutedTests:total-rows.length,testIdentities:identities,testIdentitySha256:createHash('sha256').update(JSON.stringify(identities)).digest('hex'),failedTestIdentities:rows.filter(row=>row[0]==='FAIL').map(row=>row[3]),summary:summaries[0],seconds:job.seconds};
  });
  if(runId==='38844610546')for(const job of jobs)deepStrictEqual(job.testIdentities,jobs[0].testIdentities);
  writeFileSync(`${dir}/test-verification.json`,JSON.stringify({runId,workflowRevision:collection.revision,sourceRevision:runId==='38842787230'?'cb95cf6d785c3073c192b95f0632cdae7b910894':'3434eaa455d569c18b52cf15100f77f9db251d21',jobs,limitation:'One ignored real-library benchmark is reported only as an unnamed runtime skip; no full-source pass is inferred from partial execution.'},null,2)+'\n');
  console.log(JSON.stringify({runId,jobs:jobs.map(({testIdentities,...job})=>job)}));
}
'''

